const HGT = [30, 40, 26, 46, 34, 28, 38], REST_I = 2, REST_LIFT = 13;
const X0 = -9, X1 = (N - 1) * PITCH + BW + 9, Y0 = -9, Y1 = BD + 9, MAXGAP = 12;
const STUDS = [[BW / 2, BD / 2 - 7], [BW / 2, BD / 2 + 7]], SR = 3.4, SH = 3;

